def agent_parameter_count(agent: Any) -> int:
    modules = [
        getattr(agent, name, None)
        for name in (
            "actor",
            "critic",
            "correction_gate",
            "q_network",
        )
    ]
    unique_modules = {
        id(module): module
        for module in modules
        if module is not None
    }
    return int(
        sum(
            parameter.numel()
            for module in unique_modules.values()
            for parameter in module.parameters()
        )
    )
